/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{


    EXU_CountyNum countyNum = 'TST_County';
    EXU_StreetNum streetNum = 'TST_Street';

    AddressZipCodeId zipCodeId = '9999';
    str cityName = 'TST_City';
    str addrLocation = 'TST_AddrLoc';

    EXU_InstParameters instParameters = EXU_InstParameters::find();
    AddressCountryRegionId countryRegionId = instParameters.CountryRegionId;

    EXU_DeliveryCategory deliveryCategory = "TST_DelCat";
    EXU_CategoryNum categoryNum = "TST_Catgry";

    EXU_GroupCode groupCode = EXU_GroupCode::ReadingMethod;
    EXU_GroupName groupName = 'TST_GroupName';
    EXU_GroupNum groupNum = 'TST_GroupNum';

    EXU_SupplyNum supplyNum = "TST_Supply";

    EGS_Readingsystem readingSystem = EGS_Readingsystem::Xellent;

    // =============================================
    // 1. Delete ElsmartParam
    // =============================================
    EXU_ElsmartParam elsmartParam;

    select firstonly forupdate elsmartParam
    where elsmartParam.DeliveryCategory == deliveryCategory
       && elsmartParam.EGS_ReadingSystem == readingSystem;

    if (elsmartParam.RecId)
    {
        ttsbegin;
        elsmartParam.delete();
        ttscommit;
        info(strFmt("Deleted ElsmartParam: %1", deliveryCategory));
    }
    else
    {
        info(strFmt("ElsmartParam '%1' does not exist — skipped.", deliveryCategory));
    }

    // =============================================
    // 2. Delete SupplyModel
    // =============================================
    EXU_SupplyModel newSupplyModel;

    select firstonly forupdate newSupplyModel
    where newSupplyModel.SupplyNum == supplyNum;

    if (newSupplyModel.RecId)
    {
        ttsbegin;
        newSupplyModel.delete();
        ttscommit;
        info(strFmt("Deleted SupplyModel: %1", supplyNum));
    }
    else
    {
        info(strFmt("SupplyModel '%1' does not exist — skipped.", supplyNum));
    }

    // =============================================
    // 3. Delete ReadingPlan
    // =============================================
    EXU_ReadingPlan newReadingPlan;

    select firstonly forupdate newReadingPlan
    where newReadingPlan.ReadingPlanNum == groupNum;

    if (newReadingPlan.RecId)
    {
        ttsbegin;
        newReadingPlan.delete();
        ttscommit;
        info(strFmt("Deleted ReadingPlan: %1", groupNum));
    }
    else
    {
        info(strFmt("ReadingPlan '%1' does not exist — skipped.", groupNum));
    }

    // =============================================
    // 4. Delete GroupTable
    // =============================================
    EXU_GroupTable newGroupTable;

    select firstonly forupdate newGroupTable
    where newGroupTable.GroupCode == groupCode
       && newGroupTable.GroupNum  == groupNum;

    if (newGroupTable.RecId)
    {
        ttsbegin;
        newGroupTable.delete();
        ttscommit;
        info(strFmt("Deleted GroupTable: %1, %2", groupCode, groupNum));
    }
    else
    {
        info(strFmt("GroupTable '%1, %2' does not exist — skipped.", groupCode, groupNum));
    }

    // =============================================
    // 5. Delete DeliveryRelationTable
    // =============================================
    EXU_DeliveryRelationTable newDeliveryRelationTable;

    select firstonly forupdate newDeliveryRelationTable
    where newDeliveryRelationTable.DeliveryCategory == deliveryCategory;

    if (newDeliveryRelationTable.RecId)
    {
        ttsbegin;
        newDeliveryRelationTable.delete();
        ttscommit;
        info(strFmt("Deleted DeliveryRelationTable: %1", deliveryCategory));
    }
    else
    {
        info(strFmt("DeliveryRelationTable '%1' does not exist — skipped.", deliveryCategory));
    }

    // =============================================
    // 6. Delete Category
    // =============================================
    EXU_Category newExuCategory;

    select firstonly forupdate newExuCategory
    where newExuCategory.CategoryNum == categoryNum;

    if (newExuCategory.RecId)
    {
        ttsbegin;
        newExuCategory.delete();
        ttscommit;
        info(strFmt("Deleted Category: %1", categoryNum));
    }
    else
    {
        info(strFmt("Category '%1' does not exist — skipped.", categoryNum));
    }

    // =============================================
    // 7. Delete DeliveryCategoryTable
    // =============================================
    EXU_DeliveryCategoryTable newDeliveryCategoryTable;

    select firstonly forupdate newDeliveryCategoryTable
    where newDeliveryCategoryTable.DeliveryCategory == deliveryCategory;

    if (newDeliveryCategoryTable.RecId)
    {
        ttsbegin;
        newDeliveryCategoryTable.delete();
        ttscommit;
        info(strFmt("Deleted DeliveryCategoryTable: %1", deliveryCategory));
    }
    else
    {
        info(strFmt("DeliveryCategoryTable '%1' does not exist — skipped.", deliveryCategory));
    }

    // =============================================
    // 8. Delete StreetAddrNumber (AddrLocation)
    // =============================================
    EXU_StreetAddrNumber streetAddrLoc;

    select firstonly forupdate streetAddrLoc
    where streetAddrLoc.CountryRegionId   == countryRegionId
       && streetAddrLoc.CountyNum         == countyNum
       && streetAddrLoc.StreetNum         == streetNum
       && streetAddrLoc.StreetAddrCPRType == EXU_StreetAddrCPRType::AddrLocation;

    if (streetAddrLoc.RecId)
    {
        ttsbegin;
        streetAddrLoc.delete();
        ttscommit;
        info(strFmt("Deleted StreetAddrNumber (AddrLocation): %1, %2, %3", countryRegionId, countyNum, streetNum));
    }
    else
    {
        info(strFmt("StreetAddrNumber (AddrLocation) '%1, %2, %3' does not exist — skipped.", countryRegionId, countyNum, streetNum));
    }

    // =============================================
    // 9. Delete StreetAddrNumber (ZipCode)
    // =============================================
    EXU_StreetAddrNumber streetAddr;

    select firstonly forupdate streetAddr
    where streetAddr.CountryRegionId   == countryRegionId
       && streetAddr.CountyNum         == countyNum
       && streetAddr.StreetNum         == streetNum
       && streetAddr.StreetAddrCPRType == EXU_StreetAddrCPRType::ZipCode;

    if (streetAddr.RecId)
    {
        ttsbegin;
        streetAddr.delete();
        ttscommit;
        info(strFmt("Deleted StreetAddrNumber (ZipCode): %1, %2, %3", countryRegionId, countyNum, streetNum));
    }
    else
    {
        info(strFmt("StreetAddrNumber (ZipCode) '%1, %2, %3' does not exist — skipped.", countryRegionId, countyNum, streetNum));
    }

    // =============================================
    // 10. Delete Street
    // =============================================
    EXU_Street exuStreet = EXU_Street::find(countryRegionId, countyNum, streetNum, true);

    if (exuStreet.RecId)
    {
        ttsbegin;
        exuStreet.delete();
        ttscommit;
        info(strFmt("Deleted Street: %1", streetNum));
    }
    else
    {
        info(strFmt("Street '%1' does not exist — skipped.", streetNum));
    }

    // =============================================
    // 11. Delete County
    // =============================================
    EXU_County exuCounty = EXU_County::find(countryRegionId, countyNum, true);

    if (exuCounty.RecId)
    {
        ttsbegin;
        exuCounty.delete();
        ttscommit;
        info(strFmt("Deleted County: %1", countyNum));
    }
    else
    {
        info(strFmt("County '%1' does not exist — skipped.", countyNum));
    }

    // =============================================
    // 12. Delete ZipCode
    // =============================================
    LogisticsAddressZipCode zipCode = LogisticsAddressZipCode::findZipCodeCountryRegion(zipCodeId, countryRegionId, true);

    if (zipCode.RecId)
    {
        ttsbegin;
        zipCode.delete();
        ttscommit;
        info(strFmt("Deleted ZipCode: %1", zipCodeId));
    }
    else
    {
        info(strFmt("ZipCode '%1' does not exist — skipped.", zipCodeId));
    }

    info("Installation sequence data deletion complete.");
}
